// Block (composition) — the choice of how to pay, where pressing a method acts at once (opens the card
// prompt, the cash screen, the QR scanner). Every device of a payment product has one (a POS's 결제하기, a
// counter, a terminal, a kiosk, a table order), and unless one structure holds them they disagree on
// layout, labels and order. One structure resolves that: the methods, their labels and
// their order are data, and `layout` picks a grid (a POS, a kiosk, a terminal) or a stack (a counter screen, a phone).
//
// Each method is an ActionTile, a Button: a press acts and nothing stays selected, so this is neither a
// radio group (no value persists) nor a GridList (a two-to-eight item grid would announce "grid, row 1
// of 5" with no cue that a press proceeds). It is the same fork as the product grids
// (component-usage.md § Product grids). A disabled method is skipped by the keyboard, so its reason goes
// in its `description`, which the tile reads as part of its name.
//
// ponytail: the POS pager (two rows flowing by column) and the featured or wide method tiles are not
// here; a long method list wraps. Add them when a device needs more methods than fit.
import type { ReactNode, Ref } from "react";
import { ActionTile } from "../components/ActionTile";
import { Grid } from "../layouts/Grid";
import { Stack } from "../layouts/Stack";
import "./PaymentMethodPicker.css";

export interface PaymentMethod {
  /** Stable key, passed to `onAction`. */
  id: string;
  /** The method's name, e.g. "신용카드". */
  label: string;
  /** A second line, e.g. "간편결제·지역화폐" under "QR 결제", or why the method is disabled. */
  description?: ReactNode;
  /** The method's icon. Decorative: the label names the method. */
  icon?: ReactNode;
  /** When true the method shows but cannot be pressed. Say why in `description`. */
  isDisabled?: boolean;
}

export interface PaymentMethodPickerBaseProps {
  /**
   * Size of every method tile.
   *
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /** The methods, in the order they show. */
  methods: PaymentMethod[];
  /** Called with a method's id when it is pressed. */
  onAction: (id: string) => void;
  /**
   * `grid` of vertical tiles on a wide or fixed screen (POS, kiosk, Terminal); `stack` of horizontal
   * rows on a narrow one (a counter screen, a phone).
   *
   * @default "grid"
   */
  layout?: "grid" | "stack";
  /**
   * For `grid`: the narrowest a tile may get, as a CSS length. The grid fits as many columns as this
   * allows. A POS method tile is typically 130 CSS px wide (`8.125rem`).
   *
   * @default "8rem"
   */
  minItemWidth?: string;
  /**
   * Where a grid tile sets its icon and label. `center` as a counter screen or a re-pay modal draws them;
   * `start` as a POS 결제하기 grid does (icon and label top start).
   *
   * @default "center"
   */
  align?: "center" | "start";
}

/** The set needs a name: its own `aria-label`, or the id of a visible heading. */
export type PaymentMethodPickerProps = PaymentMethodPickerBaseProps &
  (
    | { "aria-label": string; "aria-labelledby"?: never }
    | { "aria-labelledby": string; "aria-label"?: never }
  ) & {
    /** Additional class (optional). sd-payment-method-picker is always preserved. */
    className?: string;
    /** Forwarded to the root element. */
    ref?: Ref<HTMLDivElement>;
  };

export function PaymentMethodPicker({
  size = "medium",
  methods,
  onAction,
  layout = "grid",
  minItemWidth = "8rem",
  align,
  className,
  ref,
  ...labelling
}: PaymentMethodPickerProps) {
  const tiles = methods.map((m) => (
    <ActionTile
      key={m.id}
      size={size}
      orientation={layout === "grid" ? "vertical" : "horizontal"}
      align={align}
      icon={m.icon}
      label={m.label}
      description={m.description}
      isDisabled={m.isDisabled}
      onPress={() => onAction(m.id)}
    />
  ));
  const cls = className ? `sd-payment-method-picker ${className}` : "sd-payment-method-picker";
  // Grid lays out the tiles (auto-fill at minItemWidth, so two methods keep a tile's width rather than
  // stretching to halves); a list is a Stack of rows.
  return layout === "grid" ? (
    <Grid {...labelling} ref={ref as Ref<HTMLElement>} role="group" minItemWidth={minItemWidth} minItemMode="fill" gap="x-small" className={cls}>
      {tiles}
    </Grid>
  ) : (
    <Stack {...labelling} ref={ref as Ref<HTMLElement>} role="group" gap="x-small" className={cls}>
      {tiles}
    </Stack>
  );
}

/* Layout only (block-contract.md §3, §5): Grid or Stack arranges the tiles and the tiles draw
   themselves; the Block spans its parent. */
.sd-payment-method-picker {
  inline-size: 100%;
}
